def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n < 3:
        return 'C'

    opp_coops = 0
    my_coops = 0
    for me, opp in history:
        if opp == 'C':
            opp_coops += 1
        if me == 'C':
            my_coops += 1
    opp_defects = n - opp_coops
    my_defects = n - my_coops

    last_me, last_opp = history[-1]

    if opp_defects == n:
        return 'D'

    if opp_defects == 0:
        return 'C'

    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    my_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_def_streak += 1
        else:
            break

    if n >= 6:
        matches = 0
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                matches += 1
        if matches >= (n - 1) * 0.7:
            return 'C'

    if last_opp == 'D' and last_me == 'D' and my_def_streak >= 2:
        if opp_coops > 0 and opp_def_streak >= 2:
            return 'C'

    if last_opp == 'D':
        if opp_defects <= max(1, n // 10) and n > 10:
            if opp_def_streak >= 2:
                return 'D'
            return 'C'
        return 'D'

    if last_me == 'D':
        return 'C'

    return 'C'
